WITH filtered AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, LENGTH(status) AS status_length, UPPER(status) AS status_upper FROM shipments WHERE order_id IS NOT NULL AND carrier IN ('DHL', 'UPS')), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, status ORDER BY cost DESC, id) AS rank_in_group FROM filtered QUALIFY rank_in_group = 1), scored AS (SELECT *, LAG(status_length, 1) OVER w_grp AS prev_status_length, NTILE(5) OVER (PARTITION BY status ORDER BY status_length, id) AS status_length_bucket, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY rank_in_group DESC, id) AS row_seq FROM ranked WINDOW w_grp AS (PARTITION BY status ORDER BY cost, id)), with_dims AS (SELECT src.*, o.discount FROM scored src LEFT JOIN orders o ON src.order_id = o.id), deduped AS (SELECT * FROM with_dims QUALIFY ROW_NUMBER() OVER (PARTITION BY status, carrier ORDER BY status_length DESC NULLS FIRST, id) = 1), scored_shipments AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, status_length, status_upper, rank_in_group, prev_status_length, status_length_bucket, row_seq, discount, LAG(cost, 1) OVER (PARTITION BY status, order_id ORDER BY prev_status_length, id) AS prev_cost, LAG(row_seq, 2) OVER w_part AS prev_row_seq, PERCENT_RANK() OVER (PARTITION BY status, carrier ORDER BY status_length_bucket NULLS LAST) AS status_length_bucket_percent_rank FROM deduped WINDOW w_part AS (PARTITION BY status, carrier ORDER BY cost, id)), latest AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY order_id ORDER BY shipped_date DESC) AS dedup_rank FROM scored_shipments) x WHERE dedup_rank = 1) SELECT * FROM (SELECT id, order_id, cost, prev_cost, discount FROM latest) src UNPIVOT (val FOR metric IN (cost, prev_cost, discount))
